package android.content;
import java.util.*;
public class SharedPreferences {
 private final Map<String,Object> p=new HashMap<>();
 public synchronized int getInt(String k,int v){return (Integer)p.getOrDefault(k,v);}
 public synchronized long getLong(String k,long v){return (Long)p.getOrDefault(k,v);}
 public synchronized String getString(String k,String v){return (String)p.getOrDefault(k,v);}
 public synchronized boolean contains(String k){return p.containsKey(k);}
 public synchronized Map<String,?> getAll(){return new HashMap<>(p);}
 public Editor edit(){return new Editor();}
 public class Editor {
  private final Map<String,Object> changes=new HashMap<>();
  public Editor putInt(String k,int v){changes.put(k,v);return this;}
  public Editor putLong(String k,long v){changes.put(k,v);return this;}
  public Editor putString(String k,String v){changes.put(k,v);return this;}
  public Editor remove(String k){changes.put(k,null);return this;}
  public boolean commit(){synchronized(SharedPreferences.this){for(Map.Entry<String,Object> e:changes.entrySet())if(e.getValue()==null)p.remove(e.getKey());else p.put(e.getKey(),e.getValue());}return true;}
  public void apply(){commit();}
 }
}

